WITH latest AS (SELECT *, RANK() OVER (PARTITION BY promo_code ORDER BY ends_on DESC) AS latest_rank FROM promotions QUALIFY latest_rank = 1) SELECT CASE WHEN discount_pct >= 0.28 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, COUNT(*) FILTER (WHERE channel = 'mobile') AS mobile_rows, COUNT(*) AS cnt FROM latest GROUP BY CASE WHEN discount_pct >= 0.28 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING cnt >= 1 ORDER BY mobile_rows DESC NULLS LAST
